package com.bank.arch.metric;

import java.util.Arrays;

// Computes percentiles — NOT just the average — because users feel the tail.
public class LatencyProfile {
    private final int[] sorted;
    public LatencyProfile(int[] samplesMs) {
        this.sorted = samplesMs.clone();
        Arrays.sort(this.sorted);
    }
    public double average() { return Arrays.stream(sorted).average().orElse(0); }
    public int percentile(double p) {
        if (sorted.length == 0) return 0;
        int idx = (int) Math.ceil(p / 100.0 * sorted.length) - 1;
        return sorted[Math.max(0, Math.min(idx, sorted.length - 1))];
    }
    public int p50() { return percentile(50); }
    public int p95() { return percentile(95); }
    public int p99() { return percentile(99); }
}
