package com.bank.arch.decision;

import com.bank.arch.metric.LatencyProfile;
import java.util.logging.Logger;

// Decides based on VALUE, not the average: objective, tail, failure modes, operability.
public class TradeoffEvaluator {
    private static final Logger log = Logger.getLogger(TradeoffEvaluator.class.getName());
    private final int p99ObjectiveMs;
    private final double minReadiness;

    public TradeoffEvaluator(int p99ObjectiveMs, double minReadiness) {
        this.p99ObjectiveMs = p99ObjectiveMs; this.minReadiness = minReadiness;
    }

    public String decide(LatencyProfile current, LatencyProfile proposed,
                         double complexityMultiplier, double operabilityReadiness) {
        boolean currentMeetsObjective = current.p99() <= p99ObjectiveMs;
        boolean tailImproved = proposed.p99() < current.p99();
        double avgImprovement = 1.0 - proposed.average() / current.average();

        log.info(() -> String.format("avg cut=%.0f%%  current p99=%dms  proposed p99=%dms  objective=%dms",
                avgImprovement * 100, current.p99(), proposed.p99(), p99ObjectiveMs));

        // Rule 1: already meeting objective AND tail not improved → average win is cosmetic.
        if (currentMeetsObjective && !tailImproved) {
            log.warning("REJECT: already meet p99 objective; avg win does not help the tail users feel");
            return "REJECT_NO_VALUE";
        }
        // Rule 2: team cannot operate the doubled complexity → defer until ready.
        if (operabilityReadiness < minReadiness) {
            log.warning(() -> "DEFER: operability readiness " + operabilityReadiness
                    + " < " + minReadiness + " — build runbooks/observability first");
            return "DEFER_UNTIL_OPERABLE";
        }
        // Rule 3: tail improves AND closes an objective gap AND team ready → approve.
        if (tailImproved && !currentMeetsObjective) {
            log.info("APPROVE: closes an objective gap on the tail and team can operate it");
            return "APPROVE";
        }
        log.info("CONDITIONAL: seek a simpler change capturing most of the win");
        return "SEEK_SIMPLER_ALTERNATIVE";
    }
}
