package com.bank.arch;

import com.bank.arch.decision.TradeoffEvaluator;
import com.bank.arch.metric.LatencyProfile;
import java.util.logging.*;

public class ArchDecisionDemo {
    private static final Logger log = Logger.getLogger(ArchDecisionDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        // CURRENT: mostly fast, with a real tail. p99 ~190ms, under the 200ms objective.
        int[] current = buildSamples(50, 190);
        // PROPOSED: cuts the average (hot reads cached) but tail UNCHANGED (slow path same).
        int[] proposed = buildSamples(30, 190);

        LatencyProfile cur = new LatencyProfile(current);
        LatencyProfile prop = new LatencyProfile(proposed);

        TradeoffEvaluator evaluator = new TradeoffEvaluator(200, 0.7);

        log.info("=== Architecture trade-off: +40% avg speed vs 2x complexity ===");
        // complexity doubles (2.0), team only 0.5 ready to operate new components.
        String decision = evaluator.decide(cur, prop, 2.0, 0.5);
        log.info(() -> "DECISION: " + decision);
    }

    // Builds a distribution: mostly near 'fast', with a 1% tail near 'tail'.
    private static int[] buildSamples(int fast, int tail) {
        int[] s = new int[100];
        for (int i = 0; i < 99; i++) s[i] = fast + (i % 10);
        s[99] = tail; // the tail sample users actually feel
        return s;
    }
}

